\encoding UTF8
\set ON_ERROR_STOP on

-- ============================================================================
-- 007_osr_interpretations.sql
-- Записывает описания 9 шкал ОСР (модификация Т.Н. Разуваевой) в поле
-- test_scales.interpretation вместо заглушек «Результат анализа по шкале…».
-- Текст берётся протоколом DOCX для раздела «Анализ по шкалам»
-- и виден в редакторе методик в колонке «Текст заключения».
-- Обновляются все версии шкал ОСР (активные и архивные), сопоставление по scale_code.
-- Повторный запуск безопасен.
-- ============================================================================

BEGIN;

WITH t AS (
    SELECT id FROM psychology.psychological_tests WHERE test_code = 'AI_PDF_7D9D'
),
txt(scale_code, body) AS (VALUES
('SCALE_1', 'Демонстративность. Желание привлечь внимание окружающих к своим несчастьям, добиться сочувствия и понимания. Оцениваемое из внешней позиции порой как «шантаж», «истероидное выпячивание трудностей», демонстративное суицидальное поведение переживается изнутри как «крик о помощи». Наиболее суицидоопасно сочетание с эмоциональной ригидностью, когда «диалог с миром» может зайти очень далеко.'),
('SCALE_2', 'Аффективность. Доминирование эмоций над интеллектуальным контролем в оценке ситуации. Готовность реагировать на психотравмирующую ситуацию непосредственно эмоционально. В крайнем варианте – аффективная блокада интеллекта.'),
('SCALE_3', 'Уникальность. Восприятие себя, ситуации и, возможно, собственной жизни в целом как явления исключительного, не похожего на другие, и, следовательно, подразумевающего исключительные варианты выхода, в частности, суицид. Тесно связана с феноменом «непроницаемости» для опыта, т.е. с недостаточным умением использовать свой и чужой опыт.'),
('SCALE_4', 'Несостоятельность. Отрицательная концепция собственной личности. Представление о своей несостоятельности, некомпетентности, ненужности, «выключенности» из мира. Данная шкала может быть связана с представлениями о физической, интеллектуальной, моральной и прочей несостоятельностью. Несостоятельность выражает интрапунитивный радикал. Формула внешнего монолога – «Я плох».'),
('SCALE_5', 'Социальный пессимизм. Отрицательная концепция окружающего мира. Восприятие мира как враждебного, не соответствующего представлениям о нормальных или удовлетворительных для человека отношениях с окружающими. Социальный пессимизм тесно связан с экстрапунитивным стилем каузальной атрибуции. Наблюдается экстрапунитивность по формуле внутреннего монолога – «Вы все недостойны меня».'),
('SCALE_6', 'Слом культурных барьеров. Культ самоубийства. Поиск культурных ценностей и нормативов, оправдывающих суицидальное поведение или даже делающих его в какой-то мере привлекательным. Заимствование суицидальных моделей поведения из литературы и кино. В крайнем варианте – инверсия ценности смерти и жизни. В отсутствие выраженных пиков по другим шкалам это может говорить только об «экзистенции смерти». Одна из возможных внутренних причин культа смерти – доведенная до патологического максимализма смысловая установка на самодеятельность: «Вершитель собственной судьбы сам определяет конец своего существования».'),
('SCALE_7', 'Максимализм. Инфантильный максимализм ценностных установок. Распространение на все сферы жизни содержания локального конфликта в какой-то одной жизненной сфере. Невозможность компенсации. Аффективная фиксация на неудачах.'),
('SCALE_8', 'Временная перспектива. Невозможность конструктивного планирования будущего. Это может быть следствием сильной погруженности в настоящую ситуацию, трансформацией чувства неразрешимости текущей проблемы в глобальный страх неудач и поражений в будущем.'),
('SCALE_9', 'Антисуицидальный фактор. Даже при высокой выраженности всех остальных факторов есть фактор, который снимает глобальный суицидальный риск. Это глубокое понимание чувства ответственности за близких, чувство долга. Это представление о греховности самоубийства, антиэстетичности его, боязнь боли и физических страданий. В определенном смысле это показатель наличного уровня предпосылок для психокоррекционной работы.')
)
UPDATE psychology.test_scales s
SET interpretation = txt.body
FROM txt
WHERE s.scale_code = txt.scale_code
  AND s.test_id = (SELECT id FROM t)
  AND s.interpretation IS DISTINCT FROM txt.body;

COMMIT;

-- Контроль: у каждой активной шкалы должен быть полный текст
SELECT scale_code, scale_name, left(interpretation, 60) || '…' AS "начало текста"
FROM psychology.test_scales
WHERE is_active
  AND test_id = (SELECT id FROM psychology.psychological_tests WHERE test_code = 'AI_PDF_7D9D')
ORDER BY scale_code;
